using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class GangsterNeonCityFinish {
static GangsterNeonCityFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("GangsterNeonCityFinish.request"))return;File.Delete("GangsterNeonCityFinish.request");try{
var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Gangster Neon Road Facing Wall Art");string csv="FinalEnvironmentRoadReview/GangsterNeonCityPlacements.csv";var rows=File.ReadAllLines(csv);var keep=rows.Skip(1).Where(row=>{var a=row.Split(',');return !(a[0].StartsWith("Plane001")&&float.Parse(a[6])<3.1f);}).ToArray();var removed=rows.Skip(1).Except(keep).ToArray();foreach(var row in removed){var a=row.Split(',');var p=new Vector3(float.Parse(a[1]),float.Parse(a[2]),float.Parse(a[3]));var f=root.GetComponentsInChildren<MeshFilter>().SingleOrDefault(f=>Vector3.Distance(f.transform.position,p)<.02f);if(f)UnityEngine.Object.DestroyImmediate(f.gameObject);}foreach(Transform child in root.transform.Cast<Transform>().ToArray())if(child.childCount==0)UnityEngine.Object.DestroyImmediate(child.gameObject);File.WriteAllLines(csv,new[]{rows[0]}.Concat(keep));EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var fs=root.GetComponentsInChildren<MeshFilter>();File.WriteAllText("FinalEnvironmentRoadReview/GangsterNeonCityFinal.txt","SUCCESS final street-view cleanup removed "+removed.Length+" lower glazed facade placements. Final prefab instances="+fs.Length+" on "+root.transform.childCount+" building groups; shared source prefabs=36; shared mesh assets=36; placed triangles="+fs.Sum(f=>f.sharedMesh.triangles.Length/3)+". One approved atlas / one material, GPU instancing and mobile ASTC compression, distance culling, zero new Lights or colliders; native buildings unchanged.");
}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GangsterNeonCityFinal.txt",e.ToString());Debug.LogException(e);}}}
